import express from "express";
import type { Express } from "express";
import { AddTaskUseCase } from "../application/use-cases/add-task-use-case";
import { AssignTaskUseCase } from "../application/use-cases/assign-task-use-case";
import { CreateProjectUseCase } from "../application/use-cases/create-project-use-case";
import { CreateUserUseCase } from "../application/use-cases/create-user-use-case";
import { ListProjectTasksUseCase } from "../application/use-cases/list-project-tasks-use-case";
import { MarkTaskDoneUseCase } from "../application/use-cases/mark-task-done-use-case";
import { errorMiddleware } from "./http/error-middleware";
import { ProjectController } from "./http/project-controller";
import { TaskController } from "./http/task-controller";
import { UserController } from "./http/user-controller";
import { InMemoryProjectRepository } from "./persistence/in-memory-project-repository";
import { InMemoryTaskRepository } from "./persistence/in-memory-task-repository";
import { InMemoryUserRepository } from "./persistence/in-memory-user-repository";

export function createApp(): Express {
  const users = new InMemoryUserRepository();
  const projects = new InMemoryProjectRepository();
  const tasks = new InMemoryTaskRepository();

  const userController = new UserController(new CreateUserUseCase(users));
  const projectController = new ProjectController(new CreateProjectUseCase(projects));
  const taskController = new TaskController(
    new AddTaskUseCase(projects, tasks),
    new AssignTaskUseCase(tasks, users),
    new ListProjectTasksUseCase(projects, tasks),
    new MarkTaskDoneUseCase(tasks),
  );

  const app = express();
  app.use(express.json());
  app.use(userController.routes());
  app.use(projectController.routes());
  app.use(taskController.routes());
  app.use(errorMiddleware);
  return app;
}

